// Turns a double-booking collision into a result the agent can relay
// naturally, instead of a raw Postgres error propagating up through the
// tool_result. The Google Calendar event (HTTP Request, runs before this
// insert) has already been created by this point -- if we return
// success:false here, 'Insert Succeeded?' routes to 'Delete Orphaned
// Calendar Event', which deletes that event so it doesn't linger with no
// matching DB row. See KNOWN_ISSUES.md.
const input = $input.first().json;

if (input.error) {
  const msg = (input.error.message || String(input.error) || '').toLowerCase();
  const isCollision = msg.includes('excl_no_overlapping_appointments') || msg.includes('exclusion');

  return [{
    json: {
      success: false,
      error: isCollision ? 'slot_unavailable' : 'booking_failed',
      message: isCollision
        ? 'That time is no longer available -- someone else just booked it. Please choose a different slot.'
        : 'Something went wrong while booking. Please try again or choose a different slot.',
    }
  }];
}

return [{ json: input }];

// Always return the original graceful booking-failure message to the agent, regardless of whether the calendar cleanup above succeeded --
// the visitor-facing outcome ("that slot is no longer available") is the same either way. We tag cleanup status for internal logging only.
const original = $('Handle Insert Result').first().json;
const cleanupFailed = $input.first().json.error != null;

return [{
  json: {
    ...original,
    _calendar_cleanup: cleanupFailed ? 'failed' : 'ok',
  }
}];

parameters.jsonBody:
={{ (() => {
  const req = $('When Executed by Another Workflow').first().json;
  const info = $json;
  const DASHBOARD_URL = 'https://elliot-real-estate-five.vercel.app';
  const CHANNEL = { whatsapp: 'WhatsApp', chat_widget: 'website chat', email: 'email' };
  const place = [info.listing_title, info.listing_reference ? `ref ${info.listing_reference}` : null].filter(Boolean).join(', ');
  const attendees = [info.contact_email, info.agent_email].filter(Boolean).map((email) => ({ email }));
  return JSON.stringify({
    summary: `Property viewing — ${info.contact_name || 'client'}${info.listing_title ? ` — ${info.listing_title}` : ''}`,
    location: info.listing_address || undefined,
    description: [
      place ? `Property: ${place}` : null,
      info.listing_address ? `Address: ${info.listing_address}` : null,
      info.agent_name ? `Agent: ${info.agent_name}` : null,
      info.contact_phone ? `Client phone: ${info.contact_phone}` : null,
      req.notes || null,
      info.conversation_id ? `Booked by Elliot on ${CHANNEL[info.conversation_channel] || 'chat'}: ${DASHBOARD_URL}/dashboard/conversations/${info.conversation_id}` : null,
    ].filter(Boolean).join('\n'),
    start: { dateTime: req.starts_at, timeZone: info.timezone },
    end: { dateTime: req.ends_at, timeZone: info.timezone },
    attendees,
  });
})() }}

parameters.query:
-- agent_id is filled in by trg_appointments_fill_links (0030) from the
-- lead's owner; listing_id comes from 'Load Tenant + Contact Info';
-- conversation_id (0033) is the chat the viewing was booked in.
insert into appointments (tenant_id, contact_id, starts_at, ends_at, timezone, status, external_calendar_id, notes, listing_id, conversation_id)
values ($1, $2, $3, $4, $5, 'confirmed', $6, $7, nullif($8, '')::uuid, nullif($9, '')::uuid)
returning id, starts_at, ends_at, status, listing_id, conversation_id;

parameters.jsCode:
// Where a client can see a property: the agency's own page for it when it
// has one, otherwise Elliot's property page with the photos (/p/<id> on the
// dashboard; photos added in Listings or imported from Google Drive). A
// Google Drive / Dropbox folder isn't a property page, so it gets ours.
const DASHBOARD_URL = 'https://elliot-real-estate-five.vercel.app'; // change if the dashboard moves to its own domain
function propertyLink(id, url) {
  const own = String(url || '').trim();
  if (/^https?:\/\//i.test(own) && !/drive\.google\.com|dropbox\.com/i.test(own)) return own;
  return id ? `${DASHBOARD_URL}/p/${id}` : null;
}

// Normalize output for the Main Agent's tool_result formatting.
const appt = $input.first().json;
const info = $('Load Tenant + Contact Info').first().json;
return [{
  json: {
    success: true,
    appointment_id: appt.id,
    starts_at: appt.starts_at,
    ends_at: appt.ends_at,
    status: appt.status,
    listing_title: appt.listing_id ? info.listing_title || null : null,
    listing_address: appt.listing_id ? info.listing_address || null : null,
    listing_link: appt.listing_id ? propertyLink(appt.listing_id, info.listing_url) : null,
  }
}];

// Where a client can see a property: the agency's own page for it when it
// has one, otherwise Elliot's property page with the photos (/p/<id> on the
// dashboard; photos added in Listings or imported from Google Drive). A
// Google Drive / Dropbox folder isn't a property page, so it gets ours.
const DASHBOARD_URL = 'https://elliot-real-estate-five.vercel.app'; // change if the dashboard moves to its own domain
function propertyLink(id, url) {
  const own = String(url || '').trim();
  if (/^https?:\/\//i.test(own) && !/drive\.google\.com|dropbox\.com/i.test(own)) return own;
  return id ? `${DASHBOARD_URL}/p/${id}` : null;
}

// The client's confirmation email (English, then Polish), sent from the
// agency's connected Gmail -- the same account and raw RFC 2822 pattern as
// workflows 15 and 24. Times are in the agency's time zone.
const info = $('Load Tenant + Contact Info').first().json;
const booked = $input.first().json;
const req = $('When Executed by Another Workflow').first().json;
const tz = info.timezone || 'Europe/Warsaw';
const start = new Date(req.starts_at);
const end = new Date(req.ends_at);
const when = (locale) =>
  `${start.toLocaleDateString(locale, { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}, ` +
  `${start.toLocaleTimeString(locale, { timeZone: tz, hour: '2-digit', minute: '2-digit' })}–` +
  `${end.toLocaleTimeString(locale, { timeZone: tz, hour: '2-digit', minute: '2-digit' })}`;
const agency = info.tenant_name || 'our office';
const first = String(info.contact_name || '').trim().split(/\s+/)[0] || '';
const link = booked.listing_link;
const facts = [
  info.listing_price != null ? `${Number(info.listing_price).toLocaleString('pl-PL')} ${info.listing_currency || 'PLN'}${info.listing_transaction_type === 'rent' ? ' / month' : ''}` : null,
  info.listing_area_m2 ? `${Number(info.listing_area_m2)} m²` : null,
  info.listing_rooms ? `${info.listing_rooms} room${info.listing_rooms === 1 ? '' : 's'}` : null,
].filter(Boolean).join(' · ');

const en = [
  `Hi${first ? ' ' + first : ''},`,
  '',
  `Your viewing with ${agency} is confirmed.`,
  '',
  `When:     ${when('en-GB')}`,
  info.listing_title ? `Property: ${info.listing_title}${info.listing_reference ? ` (ref ${info.listing_reference})` : ''}` : null,
  facts ? `          ${facts}` : null,
  info.listing_address ? `Address:  ${info.listing_address}` : null,
  info.agent_name ? `Agent:    ${info.agent_name}` : null,
  link ? `Photos and details: ${link}` : null,
  '',
  'Need to change or cancel? Just reply to this email or send us a message.',
  '',
  `See you there,`,
  agency,
].filter((l) => l !== null);

const pl = [
  `Dzień dobry${first ? ' ' + first : ''},`,
  '',
  `potwierdzamy prezentację nieruchomości z ${agency}.`,
  '',
  `Termin:   ${when('pl-PL')}`,
  info.listing_title ? `Oferta:   ${info.listing_title}${info.listing_reference ? ` (nr ${info.listing_reference})` : ''}` : null,
  info.listing_address ? `Adres:    ${info.listing_address}` : null,
  info.agent_name ? `Agent:    ${info.agent_name}` : null,
  link ? `Zdjęcia i szczegóły: ${link}` : null,
  '',
  'Jeśli chcą Państwo zmienić lub odwołać termin, wystarczy odpowiedzieć na tę wiadomość.',
  '',
  'Do zobaczenia,',
  agency,
].filter((l) => l !== null);

const subject = `Viewing confirmed: ${start.toLocaleDateString('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short' })}, ` +
  `${start.toLocaleTimeString('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit' })}` +
  `${info.listing_title ? ' – ' + info.listing_title : ''}`;
const encodedSubject = `=?UTF-8?B?${Buffer.from(subject, 'utf8').toString('base64')}?=`;
const body = en.join('\n') + '\n\n----------------------------------------\n\n' + pl.join('\n') + '\n';
const raw =
  `To: ${info.contact_email}\r\n` +
  `Subject: ${encodedSubject}\r\n` +
  `MIME-Version: 1.0\r\n` +
  `Content-Type: text/plain; charset=UTF-8\r\n` +
  `Content-Transfer-Encoding: base64\r\n\r\n` +
  Buffer.from(body, 'utf8').toString('base64');
const encoded = Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { to: info.contact_email, subject, body, raw_message: encoded } }];

// What goes back to Elliot (workflow 01): the booking, plus whether the
// client's confirmation email went out. A failed email never fails the
// booking -- the viewing is already in the calendar and in Elliot.
const result = { ...$('Format Results').first().json };
let sentTo = null;
try {
  const sent = $('Send Confirmation Email').first().json;
  if (sent && sent.id && !sent.error) sentTo = $('Build Confirmation Email').first().json.to;
} catch (e) { /* no email on file: the email branch didn't run */ }
result.confirmation_sent_to = sentTo;
return [{ json: result }];
